package com.example.demo.lifecycle;
import com.example.demo.auth.entity.*;
import com.example.demo.auth.repository.*;
import com.example.demo.auth.security.*;
import com.example.demo.base.entity.*;
import com.example.demo.base.enums.SubscriptionPlan;
import com.example.demo.common.context.*;
import com.example.demo.common.tenant.TenantContext;
import com.example.demo.employee.entity.Employee;
import com.example.demo.onboarding.dto.OnboardingConversionRequest;
import com.example.demo.onboarding.entity.*;
import com.example.demo.onboarding.service.OnboardingService;
import com.example.demo.offboarding.entity.*;
import com.example.demo.offboarding.service.OffboardingService;
import com.example.demo.recruitment.entity.*;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @Transactional
class EmploymentLifecycleIntegrationTest {
 @Autowired EntityManager em; @Autowired OnboardingService onboarding; @Autowired OffboardingService offboarding;
 @Autowired UserDetailsServiceImpl identities; @Autowired RoleRepository roles; @Autowired UserRepository users; @Autowired UserRoleRepository grants;
 @Autowired com.example.demo.payroll.service.PayslipWorkflowService payroll; @Autowired MockMvc mvc; @Autowired JwtTokenProvider tokens;
 Organization org;Company company;Department department;JobPosition position;Candidate candidate;OnboardingPortal portal;OnboardingCandidate progress;
 void admin(){var principal=identities.loadUserByUsername("admin");SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(principal,null,principal.getAuthorities()));AccessScopeContext.set(new AccessScopeContext.ScopeData(((UserPrincipal)principal).getId(),company.getId(),null,List.of()));CompanyContext.set(company.getId());TenantContext.setTenant("public");}
 @BeforeEach void setup(){TenantContext.clear();CompanyContext.clear();AccessScopeContext.clear();org=new Organization();org.setName("Lifecycle fixture");org.setSlug("lifecycle-"+UUID.randomUUID());em.persist(org);company=new Company();company.setName("Lifecycle company");company.setSchemaName("public");company.setSchemaReady(true);company.setOrganization(org);em.persist(company);department=new Department();department.setCompany(company);department.setName("Engineering");em.persist(department);position=new JobPosition();position.setCompany(company);position.setDepartment(department);position.setName("Lifecycle Engineer");em.persist(position);candidate=new Candidate();candidate.setName("Lifecycle Candidate");candidate.setEmail(UUID.randomUUID()+"@example.invalid");em.persist(candidate);var post=new RecruitmentPost();post.setName("Lifecycle opening");post.setCompany(company);em.persist(post);var application=new Applicant();application.setCandidate(candidate);application.setRecruitment(post);application.setCompany(company);application.setStatus(Applicant.ApplicantStatus.HIRED);em.persist(application);portal=new OnboardingPortal();portal.setTitle("New joiners");portal.setCompany(company);em.persist(portal);em.flush();admin();var stage=new OnboardingStage();stage.setTitle("Orientation");stage.setSequence(1);onboarding.createStage(portal.getId(),stage);var request=new OnboardingCandidate();request.setCandidate(candidate);progress=onboarding.addCandidate(portal.getId(),request);em.flush();}
 @AfterEach void clear(){SecurityContextHolder.clearContext();AccessScopeContext.clear();CompanyContext.clear();TenantContext.clear();}
 OnboardingConversionRequest conversion(){var form=new OnboardingConversionRequest();form.setDateJoining(LocalDate.now());form.setDepartmentId(department.getId());form.setJobPositionId(position.getId());return form;}
 void finishOnboarding(){for(var row:onboarding.listCandidateStages(progress.getId())) onboarding.completeCandidateStage(row.getId());onboarding.completeOnboarding(progress.getId());}
 Employee employee(){var user=new User();user.setUsername("lifecycle-"+UUID.randomUUID());user.setEmail(user.getUsername()+"@example.invalid");user.setPassword("fixture-only");em.persist(user);var role=new UserRole();role.setUser(user);role.setCompany(company);role.setRole(roles.findByName(Role.RoleName.EMPLOYEE).orElseThrow());role.setAccessScope(UserRole.AccessScope.SELF);em.persist(role);user.getUserRoles().add(role);var employee=new Employee();employee.setFirstName("Lifecycle Employee");employee.setEmail(user.getEmail());employee.setCompany(company);employee.setUser(user);em.persist(employee);em.flush();return employee;}
 EmployeeOffboarding departure(Employee employee,LocalDate date){var r=new EmployeeOffboarding();r.setEmployee(employee);r.setExitDate(date);r.setReasonOfLeaving("Synthetic lifecycle test");return offboarding.create(r,1L,"Test HR");}
 void finishTasks(EmployeeOffboarding r){for(var task:offboarding.listEmployeeTasks(r.getId()))offboarding.completeEmployeeTask(task.getId());em.flush();}
 @Test void completionAndStageAdvanceCannotSkipPendingTasks(){var task=new CandidateTask();task.setTitle("Verify documents");task.setStage(onboarding.listCandidateStages(progress.getId()).getFirst().getStage());onboarding.addCandidateTask(progress.getId(),task);assertThatThrownBy(()->onboarding.completeOnboarding(progress.getId())).hasMessageContaining("Complete every");assertThatThrownBy(()->onboarding.advanceStage(progress.getId())).hasMessageContaining("tasks first");onboarding.completeTask(task.getId());finishOnboarding();assertThat(progress.getStatus()).isEqualTo(OnboardingCandidate.OnboardingStatus.COMPLETED);}
 @Test void conversionIsExplicitAtomicAndIdempotent(){assertThatThrownBy(()->onboarding.convertCandidate(progress.getId(),conversion())).hasMessageContaining("Complete the onboarding");finishOnboarding();var result=onboarding.convertCandidate(progress.getId(),conversion());Long id=((Number)result.get("employeeId")).longValue();assertThat(candidate.getEmployeeId()).isEqualTo(id);var employee=em.find(Employee.class,id);assertThat(employee.getCompany().getId()).isEqualTo(company.getId());assertThat(employee.getUser()).isNotNull();assertThat(grants.findByUserId(employee.getUser().getId())).allMatch(g->g.getRole().getName()==Role.RoleName.EMPLOYEE);assertThat(onboarding.convertCandidate(progress.getId(),conversion()).get("employeeId")).isEqualTo(id);}
 @Test void conversionCannotDuplicateExistingEmployeeEmail(){finishOnboarding();var employee=employee();employee.setEmail(candidate.getEmail());em.flush();assertThatThrownBy(()->onboarding.convertCandidate(progress.getId(),conversion())).hasMessageContaining("already exists");assertThat(candidate.getEmployeeId()).isNull();}
 @Test void conversionUsesRealPlanCapacity(){finishOnboarding();org.setSubscriptionPlan(SubscriptionPlan.FREE);for(int i=0;i<20;i++){var e=new Employee();e.setFirstName("Quota fixture "+i);e.setCompany(company);em.persist(e);}em.flush();assertThatThrownBy(()->onboarding.convertCandidate(progress.getId(),conversion())).hasMessageContaining("limit");assertThat(candidate.getEmployeeId()).isNull();}
 @Test void existingEmployeeOnboardingUsesRealLinkAndDoesNotCreateEmployee(){var employee=employee();var result=onboarding.initiateOnboarding(employee.getId(),portal.getId());var row=onboarding.getCandidateById(((Number)result.get("id")).longValue());assertThat(row.getCandidate().getEmployeeId()).isEqualTo(employee.getId());assertThat(row.getCandidate().getName()).contains("Lifecycle Employee");assertThat(onboarding.initiateOnboarding(employee.getId(),portal.getId()).get("id")).isEqualTo(result.get("id"));}
 @Test void onlyHiredCandidatesCanBeAddedAndEnrolmentCannotDuplicate(){assertThatThrownBy(()->{var duplicate=new OnboardingCandidate();duplicate.setCandidate(candidate);onboarding.addCandidate(portal.getId(),duplicate);}).hasMessageContaining("already has onboarding");var c=new Candidate();c.setName("Not hired");em.persist(c);var r=new OnboardingCandidate();r.setCandidate(c);assertThatThrownBy(()->onboarding.addCandidate(portal.getId(),r)).hasMessageContaining("Only a hired candidate");}
 @Test void departureEndsCompanyAccessAndOldJwtBeforeClearance() throws Exception {var employee=employee();var details=identities.loadUserByUsername(employee.getUser().getUsername());String jwt=tokens.generateToken(new UsernamePasswordAuthenticationToken(details,null,details.getAuthorities()),company.getId());var record=departure(employee,LocalDate.now());assertThat(employee.isActive()).isFalse();assertThat(employee.getUser().isActive()).isFalse();assertThat(grants.findByUserId(employee.getUser().getId())).noneMatch(g->g.isEffectiveOn(LocalDate.now()));assertThat(offboarding.completionReadiness(record.getId()).get("ready")).isEqualTo(false);mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+jwt).header("X-Company-Id",company.getId().toString())).andExpect(status().isUnauthorized());}
 @Test void completionRequiresChecklistAssetsAndPaidPayroll(){var employee=employee();var asset=new com.example.demo.asset.entity.Asset();asset.setAssetName("Test laptop");asset.setAssetId(UUID.randomUUID().toString());asset.setCompany(company);em.persist(asset);var assignment=new com.example.demo.asset.entity.AssetAssignment();assignment.setAsset(asset);assignment.setEmployee(employee);em.persist(assignment);var payslip=new com.example.demo.payroll.entity.Payslip();payslip.setEmployee(employee);payslip.setCompany(company);payslip.setNetPay(java.math.BigDecimal.TEN);payslip.setStatus(com.example.demo.payroll.entity.Payslip.PayslipStatus.CONFIRMED);em.persist(payslip);var record=departure(employee,LocalDate.now());assertThatThrownBy(()->offboarding.complete(record.getId())).hasMessageContaining("Pending task");finishTasks(record);assertThatThrownBy(()->offboarding.complete(record.getId())).hasMessageContaining("asset").hasMessageContaining("payslip");assignment.setIsReturned(true);assignment.setReturnedDate(LocalDate.now());payslip.setStatus(com.example.demo.payroll.entity.Payslip.PayslipStatus.PAID);em.flush();assertThat(offboarding.complete(record.getId()).getStatus()).isEqualTo(EmployeeOffboarding.OffboardingStatus.COMPLETED);assertThat(offboarding.complete(record.getId()).getStatus()).isEqualTo(EmployeeOffboarding.OffboardingStatus.COMPLETED);}
 @Test void futureDepartureRetainsAccessUntilDueAndRecoversOverdueExit(){var employee=employee();var r=departure(employee,LocalDate.now().plusDays(5));assertThat(employee.isActive()).isTrue();assertThatThrownBy(()->offboarding.activateOffboardingById(r.getId())).hasMessageContaining("not arrived");var changed=new EmployeeOffboarding();changed.setExitDate(LocalDate.now().minusDays(1));offboarding.update(r.getId(),changed);assertThat(employee.isActive()).isFalse();assertThat(employee.getUser().isActive()).isFalse();}
 @Test void approvedResignationStartsDatedWorkflowOnce(){var employee=employee();var request=new ResignationLetter();request.setEmployee(employee);request.setPlannedToLeaveOn(LocalDate.now().plusDays(10));request.setTitle("Synthetic resignation");var r=offboarding.createResignation(request);offboarding.approveResignation(r.getId());offboarding.approveResignation(r.getId());assertThat(offboarding.getByEmployee(employee.getId())).hasSize(1);assertThat(employee.isActive()).isTrue();assertThatThrownBy(()->offboarding.rejectResignation(r.getId())).hasMessageContaining("pending");}
 @Test void platformAdminCannotBeAccidentallyOffboarded(){var employee=employee();var role=new UserRole();role.setUser(employee.getUser());role.setRole(roles.findByName(Role.RoleName.PLATFORM_SUPER_ADMIN).orElseThrow());role.setAccessScope(UserRole.AccessScope.ENTERPRISE);em.persist(role);em.flush();assertThatThrownBy(()->departure(employee,LocalDate.now())).hasMessageContaining("platform administrator");assertThat(employee.isActive()).isTrue();}
 @Test void finalPayrollFollowsSubmissionApprovalAndPaymentTransitions(){var employee=employee();var p=new com.example.demo.payroll.entity.Payslip();p.setEmployee(employee);p.setCompany(company);p.setNetPay(java.math.BigDecimal.TEN);em.persist(p);em.flush();assertThatThrownBy(()->payroll.markPaid(p.getId(),"test",LocalDate.now(),1L,"Test accountant")).hasMessageContaining("Approved");payroll.submit(p.getId(),1L,"Test HR");payroll.approve(p.getId(),1L,"Test accountant");var paid=payroll.markPaid(p.getId(),"synthetic-settlement",LocalDate.now(),1L,"Test accountant");assertThat(paid.getStatus()).isEqualTo(com.example.demo.payroll.entity.Payslip.PayslipStatus.PAID);assertThat(paid.getPaymentReference()).isEqualTo("synthetic-settlement");}
 @Test void legacyDeparturesRevokeRemainingLoginWithoutDeletingHistory(){var employee=employee();var record=new EmployeeOffboarding();record.setEmployee(employee);record.setExitDate(LocalDate.now().minusDays(1));record.setEmployeeDeactivatedAt(LocalDateTime.now().minusDays(1));employee.setActive(false);em.persist(record);em.flush();offboarding.activateOffboardingById(record.getId());assertThat(employee.getUser().isActive()).isFalse();assertThat(em.find(EmployeeOffboarding.class,record.getId())).isNotNull();assertThat(em.find(Employee.class,employee.getId())).isNotNull();}
 @Test void companyBoundariesApplyToChecklistAndOffboarding(){var employee=employee();var r=departure(employee,LocalDate.now().plusDays(5));Long taskId=offboarding.listEmployeeTasks(r.getId()).getFirst().getId();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("limited-hr",null,List.of(new SimpleGrantedAuthority("ROLE_HR_MANAGER"))));AccessScopeContext.set(new AccessScopeContext.ScopeData(1L,99999L,UserRole.AccessScope.BRANCH,List.of(99999L)));assertThatThrownBy(()->onboarding.getCandidateById(progress.getId())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->offboarding.getById(r.getId())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->offboarding.completeEmployeeTask(taskId)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
}
